using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PurgingAnchorCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PurgingAnchorCustomDescription", order = 0)]
public class PurgingAnchorCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PurgingAnchorAction purgingAnchorAction = battleAction as PurgingAnchorAction;
		return purgingAnchorAction.PurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)) + "\n" + Smart.Format(GetRawLocalizedDescription(battleAction), purgingAnchorAction.PurifyAmountToIncrease);
	}
}
